// Node 1: Load Sample Data (synthetic). In the full version this comes from Google Sheets.
return [{ json: {
  config: { cycle: 2, lambda: 0.5, targetDays: 3, debtDecay: 0.5, rulesVersion: "v1.0" },
  wards: [
    { ward_id: "W1", name: "Riverside",   stock: 20, daily_need: 40, vulnerability: 5, secondary_access: "no" },
    { ward_id: "W2", name: "Market Area", stock: 70, daily_need: 30, vulnerability: 2, secondary_access: "yes" },
    { ward_id: "W3", name: "Old Town",    stock: 15, daily_need: 35, vulnerability: 4, secondary_access: "no" },
    { ward_id: "W4", name: "Hill View",   stock: 30, daily_need: 20, vulnerability: 3, secondary_access: "no" },
    { ward_id: "W5", name: "Lakeside",    stock: 10, daily_need: 30, vulnerability: 4, secondary_access: "no" },
    { ward_id: "W6", name: "East Colony", stock: 25, daily_need: 25, vulnerability: 3, secondary_access: "yes" }
  ],
  warehouses: [ { wh_id: "WH-A", stock: 120 }, { wh_id: "WH-B", stock: 80 } ],
  roads: [
    { ward_id: "W1", wh_id: "WH-A", status: "open" },    { ward_id: "W1", wh_id: "WH-B", status: "open" },
    { ward_id: "W2", wh_id: "WH-A", status: "open" },
    { ward_id: "W3", wh_id: "WH-A", status: "blocked" }, { ward_id: "W3", wh_id: "WH-B", status: "slow" },
    { ward_id: "W4", wh_id: "WH-A", status: "open" },    { ward_id: "W4", wh_id: "WH-B", status: "slow" },
    { ward_id: "W5", wh_id: "WH-A", status: "slow" },    { ward_id: "W5", wh_id: "WH-B", status: "blocked" },
    { ward_id: "W6", wh_id: "WH-A", status: "blocked" }, { ward_id: "W6", wh_id: "WH-B", status: "blocked" }
  ],
  ledger: [
    { ward_id: "W1", debt: 0.2 }, { ward_id: "W2", debt: 0 }, { ward_id: "W3", debt: 0.8 },
    { ward_id: "W4", debt: 0 },   { ward_id: "W5", debt: 0.5 }, { ward_id: "W6", debt: 0 }
  ]
}}];

// Node 2: Score need + road access + fairness debt, then build Plan A and Plan B.
// Deterministic JavaScript. No AI is used for any number.
const d = $input.first().json;
const { lambda, targetDays } = d.config;
const supply = d.warehouses.reduce((s, w) => s + Number(w.stock), 0);
const factor = { open: 1, slow: 0.6, blocked: 0 };

const rows = d.wards.map(w => {
  const need = Math.max(0, Number(w.daily_need) * targetDays - Number(w.stock));
  // best available route to any warehouse
  const routes = d.roads.filter(r => r.ward_id === w.ward_id)
    .map(r => ({ wh: r.wh_id, status: r.status, f: factor[r.status] ?? 0 }))
    .sort((a, b) => b.f - a.f);
  const best = routes[0] || { wh: null, status: "blocked", f: 0 };
  const debt = Number((d.ledger.find(l => l.ward_id === w.ward_id) || {}).debt || 0);
  return {
    ward_id: w.ward_id, name: w.name, need, daily: Number(w.daily_need),
    vulnerability: Number(w.vulnerability), roadFactor: best.f, route: best.f > 0 ? best.wh : null,
    routeStatus: best.status, debt, secondary: w.secondary_access === "yes" ? 0.15 : 0
  };
});

const maxNeed = Math.max(...rows.map(r => r.need), 1);
rows.forEach(r => {
  const needScore = (r.need / maxNeed) * (r.vulnerability / 5);
  r.priority = Number(Math.max(0, needScore * r.roadFactor + lambda * r.debt - r.secondary).toFixed(3));
});

const reachable = rows.filter(r => r.roadFactor > 0);

// proportional fill by priority, capped at each ward's need, leftovers redistributed
function fill(items, pool, alloc) {
  let left = pool;
  for (let k = 0; k < 10 && left > 0; k++) {
    const open = items.filter(r => alloc[r.ward_id] < r.need);
    const sumP = open.reduce((s, r) => s + r.priority, 0);
    if (!open.length || sumP === 0) break;
    let given = 0;
    open.forEach(r => {
      const share = Math.floor(left * r.priority / sumP);
      const g = Math.min(share, r.need - alloc[r.ward_id]);
      alloc[r.ward_id] += g; given += g;
    });
    if (given === 0) break;
    left -= given;
  }
  return left;
}

// Plan A: need-based (priority-proportional)
const allocA = {}; reachable.forEach(r => allocA[r.ward_id] = 0);
fill(reachable, supply, allocA);

// Plan B: minimum coverage first (one day of need), then the rest by priority
const allocB = {}; reachable.forEach(r => allocB[r.ward_id] = 0);
let poolB = supply;
[...reachable].sort((a, b) => b.priority - a.priority).forEach(r => {
  const m = Math.min(r.need, r.daily, poolB); allocB[r.ward_id] += m; poolB -= m;
});
fill(reachable, poolB, allocB);

return [{ json: { ...d, supply, rows, planA: allocA, planB: allocB,
  unreachable: rows.filter(r => r.roadFactor === 0).map(r => r.name) } }];

// Node 3: Compare the two plans and write a plain-language Fairness Report (template-based).
// Optional upgrade: replace the report text with an LLM node that only rewrites these numbers.
const d = $input.first().json;
const metrics = plan => {
  let unmet = 0, lowest = 1, below50 = [];
  d.rows.forEach(r => {
    const a = plan[r.ward_id] || 0;
    unmet += Math.max(0, r.need - a);
    if (r.roadFactor > 0 && r.need > 0) {
      const c = a / r.need; lowest = Math.min(lowest, c);
      if (c < 0.5) below50.push(r.name);
    }
  });
  return { totalUnmetNeed: unmet, lowestCoveragePct: Math.round(lowest * 100), wardsBelow50: below50 };
};
const mA = metrics(d.planA), mB = metrics(d.planB);
const recommended = (mB.lowestCoveragePct - mA.lowestCoveragePct >= 5) ? "B" : "A";
const top = [...d.rows].sort((a, b) => b.priority - a.priority).slice(0, 3);

const lines = [];
lines.push(`FAIRNESS REPORT - Cycle ${d.config.cycle} (supply ${d.supply} units, rules ${d.config.rulesVersion})`);
lines.push(`Top priorities: ` + top.map(r => `${r.name} (score ${r.priority}${r.debt > 0 ? ", fairness debt " + r.debt : ""})`).join("; ") + ".");
const rerouted = d.rows.filter(r => r.route && r.routeStatus !== "open");
if (rerouted.length) lines.push(`Routing: ` + rerouted.map(r => `${r.name} served via ${r.route} (${r.routeStatus} road)`).join("; ") + ".");
if (d.unreachable.length) lines.push(`Unreachable this cycle: ${d.unreachable.join(", ")}. Their fairness debt carries over to the next cycle.`);
lines.push(`Plan A (need-based): unmet need ${mA.totalUnmetNeed}, worst-covered ward ${mA.lowestCoveragePct}%.`);
lines.push(`Plan B (minimum-coverage): unmet need ${mB.totalUnmetNeed}, worst-covered ward ${mB.lowestCoveragePct}%.`);
lines.push(`Trade-off: Plan A follows priority scores most closely; Plan B protects the worst-off wards first.`);
lines.push(`Recommendation: Plan ${recommended}. The officer makes the final decision.`);

return [{ json: { ...d, metrics: { A: mA, B: mB }, recommended, report: lines.join("\n") } }];

// Node 4: Apply the approved plan, write the dispatch order, and update the Fairness Debt ledger.
// approvedPlan defaults to the recommendation. In the full version it comes from the Telegram approval.
const d = $input.first().json;
const approvedPlan = d.approvedPlan || d.recommended;
const plan = approvedPlan === "A" ? d.planA : d.planB;
const sumNeedReach = d.rows.filter(r => r.roadFactor > 0).reduce((s, r) => s + r.need, 0) || 1;

const dispatch = d.rows.filter(r => r.route).map(r => ({
  cycle: d.config.cycle, ward_id: r.ward_id, ward: r.name, from: r.route,
  units: plan[r.ward_id] || 0, plan: approvedPlan
}));

const nextLedger = d.rows.map(r => {
  const alloc = plan[r.ward_id] || 0;
  const fair = Math.min(r.need, d.supply * r.need / sumNeedReach);
  const shortfall = r.roadFactor === 0 ? 1 : (fair > 0 ? Math.max(0, (fair - alloc) / fair) : 0);
  const newDebt = Number((d.config.debtDecay * r.debt + shortfall).toFixed(3));
  return { ward_id: r.ward_id, ward: r.name, allocated: alloc, old_debt: r.debt, new_debt: newDebt };
});

const audit = { cycle: d.config.cycle, approvedPlan, rulesVersion: d.config.rulesVersion,
  lambda: d.config.lambda, targetDays: d.config.targetDays, debtDecay: d.config.debtDecay,
  timestamp: new Date().toISOString() };

return [{ json: { approvedPlan, dispatch, nextLedger, audit, report: d.report, metrics: d.metrics } }];
